insert into public.datasets (id, provider, product, version, url, access_url, native_resolution, unit, citation, limitations) values ('mars-mola-megdr-v2', 'NASA PDS Geosciences Node', 'Mars Global Surveyor Mars Orbiter Laser Altimeter Mission Experiment Gridded Data Records: topography', '2.0 / PDS4 maintained bundle', 'https://pds-geosciences.wustl.edu/missions/mgs/megdr.html', 'https://pds-geosciences.wustl.edu/mgs/urn-nasa-pds-mgs_mola_topography_derived/meg128/megt00n090hb.img', '{"value":128,"unit":"pixels per degree","approximateMetersAtEquator":463}'::jsonb, 'm above MOLA areoid', 'Smith, D. E., M. T. Zuber, G. A. Neumann, E. A. Guinness, and S. Slavney (2003). Mars Global Surveyor Laser Altimeter Mission Experiment Gridded Data Record, MGS-M-MOLA-5-MEGDR-L3-V1.0, NASA Planetary Data System. https://doi.org/10.17189/1519460', '["The gridded DEM includes interpolation between altimetry tracks.","Its approximately 463 m equatorial sampling is coarser than the Earth DEM and must not be visually over-interpreted."]'::jsonb) on conflict (id) do update set provider = excluded.provider, product = excluded.product, version = excluded.version, url = excluded.url, access_url = excluded.access_url, native_resolution = excluded.native_resolution, unit = excluded.unit, citation = excluded.citation, limitations = excluded.limitations;
